paragraph.math:
$$\begin{array}{l}
  {\mathbf{a} = \Delta x\mathbf{i} + f_{x}\left( {x_{i},y_{j}} \right)\Delta x\mathbf{k}} \\
  {\mathbf{b} = \Delta y\mathbf{j} + f_{y}\left( {x_{i},y_{j}} \right)\Delta y\mathbf{k}}
  \end{array}$$

$$\begin{array}{l}
  {\mathbf{a} \times \mathbf{b} = \left| \begin{array}{llc}
  \mathbf{i} & \mathbf{j} & \mathbf{k} \\
  {\Delta x} & 0 & {f_{x}\left( {x_{i},y_{j}} \right)\Delta x} \\
  0 & {\Delta y} & {f_{y}\left( {x_{i},y_{j}} \right)\Delta y}
  \end{array} \right|} \\
  {\phantom{\mathbf{a} \times \mathbf{b}} = - f_{x}\left( {x_{i},y_{j}} \right)\Delta x\Delta y\mathbf{i} - f_{y}\left( {x_{i},y_{j}} \right)\Delta x\Delta y\mathbf{j} + \Delta x\Delta y\mathbf{k}} \\
  {\phantom{\mathbf{a} \times \mathbf{b}} = \left\lbrack {- f_{x}\left( {x_{i},y_{j}} \right)\mathbf{i} - f_{y}\left( {x_{i},y_{j}} \right)\mathbf{j} + \mathbf{k}} \right\rbrack\Delta A}
  \end{array}$$
